def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        base = 18.0 if hp > 3 else 45.0
        return max(0.0, min(budget, base))

    yesterday_bids = []
    david_bid = None
    pressure = 0.0
    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            yesterday_bids.append(float(bid))
            pressure = max(pressure, float(bid))
            if oid == 'David':
                david_bid = float(bid)

    competitors = 1 + len(alive)
    units = int(supply / WATER_REQ)
    scarcity = units < competitors
    semi_tight = units <= max(1, competitors - 1)

    if david_bid is None:
        david_bid = pressure if pressure > 0 else 70.0

    if hp <= 2 or no_water_days >= 2:
        bid = max(0.95 * DAILY_SALARY, david_bid + 2.0)
    elif scarcity:
        if hp <= 4 or no_water_days >= 1:
            bid = max(0.88 * DAILY_SALARY, david_bid + 1.0)
        else:
            bid = 24.0
    elif semi_tight:
        if hp <= 4:
            bid = max(60.0, min(0.9 * DAILY_SALARY, david_bid * 0.9))
        else:
            bid = 28.0
    else:
        if hp <= 3:
            bid = 52.0
        else:
            bid = 16.0 + min(8.0, float(day))

    if budget < bid:
        if hp <= 2 or no_water_days >= 2:
            return max(0.0, budget)
        reserve_floor = max(0.0, (10 - float(day)) * 8.0)
        if budget > reserve_floor:
            return max(0.0, min(budget, bid))
        return max(0.0, min(budget, 12.0))

    if hp > 5 and no_water_days == 0 and scarcity and david_bid >= 100.0:
        bid = min(bid, 20.0)

    return max(0.0, min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opps = {oid: o for oid, o in opponents_status.items() if o['alive']}

    # Extract yesterday's highest bid from alive opponents
    max_prev_bid = 0.0
    for opp in alive_opps.values():
        prev = opp.get('previous_trace', {})
        if prev and 'bid' in prev and prev['bid'] is not None:
            max_prev_bid = max(max_prev_bid, prev['bid'])

    # Base safety: if no water for days, bid high
    if my_status['no_water_days'] >= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    # If we have good hp, be conservative
    if my_status['hp'] > 5:
        # Try to underbid the previous max to let them waste budget
        if max_prev_bid > 0:
            target = max_prev_bid * 0.95
        else:
            target = DAILY_SALARY * 0.5
        return min(my_status['budget'], max(DAILY_SALARY * 0.15, target))
    else:
        # hp is moderate/low, need water
        if max_prev_bid > 0 and max_prev_bid < DAILY_SALARY * 0.9:
            # Outbid slightly
            target = max_prev_bid + 1.0
        else:
            target = DAILY_SALARY * 0.75
        return min(my_status['budget'], max(DAILY_SALARY * 0.2, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    EPISODE_DAYS = 10 

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']
    current_supply = day_context['supply']

    max_winners = int(current_supply // WATER_REQ)

    base_bid = DAILY_SALARY * 0.85 

    if max_winners <= 2: 
        base_bid *= 1.1
    elif max_winners == 3: 
        base_bid *= 1.05

    if current_day > EPISODE_DAYS * 0.6: 
        base_bid *= 1.1
    elif current_day > EPISODE_DAYS * 0.8: 
        base_bid *= 1.2

    highest_prev_competitive_bid = 0.0

    for agent_id, opp_data in opponents_status.items():
        if opp_data['alive']:
            prev = opp_data.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                if prev['bid'] > DAILY_SALARY * 0.2: 
                    highest_prev_competitive_bid = max(highest_prev_competitive_bid, prev['bid'])

    if highest_prev_competitive_bid > 0:
        calculated_bid = max(base_bid, highest_prev_competitive_bid + 2.0)
    else:
        calculated_bid = base_bid

    if my_hp <= 2:
        calculated_bid = max(calculated_bid, my_budget * 0.95)
        calculated_bid = max(calculated_bid, DAILY_SALARY * 1.2) 

    final_bid = min(my_budget, calculated_bid)

    if final_bid <= 0 and my_budget > 0:
        final_bid = min(my_budget, DAILY_SALARY * 0.1) 

    return final_bid
